async function login(e){e.preventDefault();const submit=$("#loginForm button[type=submit]")||$("#loginForm button");if(submit){submit.disabled=true;submit.textContent="Přihlašuji…"}msg("#loginMsg","Ověřuji přihlášení…");try{const credentials={email:$("#loginEmail").value.trim(),password:$("#loginPassword").value};const next=await auth("token?grant_type=password",credentials);if(!next.access_token)throw Error("Server nevrátil přihlašovací relaci.");session=next;sessionStorage.setItem("opravao_admin_session",JSON.stringify(session));msg("#loginMsg","Přihlášení ověřeno, kontroluji přístup správce…");await api("dashboard");$("#login").classList.add("hidden");$("#userEmail").textContent=session.user?.email||"Správce";try{await refresh()}catch(err){msg("#leadNotice","Nepodařilo se načíst data: "+err.message,true)}}catch(e){session=null;sessionStorage.removeItem("opravao_admin_session");msg("#loginMsg","Přihlášení se nezdařilo: "+(e.message||"Zkontrolujte připojení a přihlašovací údaje."),true)}finally{if(submit){submit.disabled=false;submit.textContent="Přihlásit se"}}}
