async function refresh(){const d=await getRes("dashboard");leads=d.leads||[];partners=d.partners||[];revenue=d.revenue||[];settings=Object.fromEntries((d.settings||[]).map(x=>[x.key,x.value]));$("#mLeads").textContent=leads.length;$("#mNew").textContent=leads.filter(x=>["new","review"].includes(x.status)).length;$("#mDue").textContent=money(revenue.filter(x=>["pending","invoiced","overdue"].includes(x.status)).reduce((a,x)=>a+Number(x.amount||0),0));$("#mPaid").textContent=money(revenue.filter(x=>x.status==="paid").reduce((a,x)=>a+Number(x.amount||0),0));$("#priceSummary").textContent=money(settings.lead_pricing?.standard||149)+" / přijatá poptávka";$("#recentRows").innerHTML=leads.slice(0,6).map(x=>'<tr'+(x.due_at&&x.due_at<new Date().toISOString().slice(0,10)&&["pending","invoiced","overdue"].includes(x.status)?' class="billing-late"':'')+'><td>'+esc(when(x.created_at))+'</td><td>'+esc(x.payload?.repairType||x.note||"Oprava")+'</td><td>'+esc(x.place)+'</td><td>'+esc(x.email||x.phone)+'</td><td><span class="status">'+esc(human(x.status))+'</span></td></tr>').join("")||'<tr><td colspan="5" class="empty">Zatím bez poptávek.</td></tr>';$("#distLead").innerHTML='<option value="">Vyberte prověřenou poptávku</option>'+leads.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.payload?.repairType||x.note||"Oprava")+" · "+esc(x.place)+" · "+esc(when(x.created_at))+"</option>").join("");$("#distPartner").innerHTML='<option value="">Vyberte opraváře</option>'+partners.filter(x=>x.active&&x.status==="approved").map(x=>'<option value="'+esc(x.id)+'">'+esc(x.company_name)+" · "+money(x.price_per_lead)+"</option>").join("");if(settings.lead_pricing)Object.entries(settings.lead_pricing).forEach(([k,v])=>{const el=$('#pricingForm [name="'+k+'"]');if(el)el.value=v});const partnerRate=$('#partnerForm [name="price_per_lead"]');if(partnerRate&&settings.lead_pricing?.standard)partnerRate.value=settings.lead_pricing.standard;if(settings.business_model)for(const k of ["subscription_enabled","commission_enabled","featured_listing_enabled"]){const e=$('#pricingForm [name="'+k+'"]');if(e)e.checked=!!settings.business_model[k]}renderLeads();renderPartners();await loadDistribution();await loadRevenue()}
async function renderLeads(){const q=($("#searchLead")?.value||"").toLowerCase(),st=$("#filterStatus")?.value||"";const shown=leads.filter(x=>(!st||x.status===st)&&[x.place,x.email,x.phone,x.name,x.note,x.assigned_to,x.next_action,x.payload?.repairType].join(" ").toLowerCase().includes(q));$("#leadFilterSummary").textContent="Zobrazeno "+shown.length+" z "+leads.length+" poptávek";$("#exportLeads").disabled=!shown.length;$("#leadRows").innerHTML=shown.map(x=>'<tr><td>'+esc(when(x.created_at))+'</td><td><b>'+esc(x.payload?.repairType||x.note||"Oprava")+'</b><br>'+esc(x.name)+'<br>'+(x.phone?esc(x.phone)+'<br>':'')+esc(x.email)+'</td><td>'+esc(x.place)+'<br>'+esc(x.region)+'</td><td><select data-status="'+esc(x.id)+'">'+["new","review","contacted","waiting_customer","preparing_quote","quote_sent","waiting_decision","ordered","partner_assigned","completed","closed"].map(s=>'<option value="'+s+'" '+(s===x.status?"selected":"")+'>'+esc(human(s))+"</option>").join("")+'</select></td><td><input data-owner="'+esc(x.id)+'" placeholder="Odpovědný" value="'+esc(x.assigned_to)+'"><br><input data-next="'+esc(x.id)+'" placeholder="Další krok" value="'+esc(x.next_action)+'"></td><td><button class="button alt" data-save-lead="'+esc(x.id)+'">Uložit</button> <button class="button alt" data-reply-lead="'+esc(x.id)+'">Odpovědět</button><small style="display:block">'+(Array.isArray(x.communication)?x.communication.length:0)+' zpráv</small></td></tr>').join("")||'<tr><td colspan="6" class="empty">Žádné odpovídající poptávky.</td></tr>';document.querySelectorAll("[data-save-lead]").forEach(b=>b.onclick=async()=>{const id=b.dataset.saveLead;b.disabled=true;b.textContent="Ukládám…";try{await api("",{action:"update_lead",id,status:$('[data-status="'+id+'"]').value,assigned_to:$('[data-owner="'+id+'"]').value,next_action:$('[data-next="'+id+'"]').value},"PATCH");msg("#leadNotice","Poptávka uložena.");await refresh()}catch(e){msg("#leadNotice",e.message,true)}finally{b.disabled=false;b.textContent="Uložit"}})}
let replyRequestId=null;
document.addEventListener("click",e=>{
 const b=e.target.closest("[data-reply-lead]");if(!b)return;
 const lead=leads.find(x=>x.id===b.dataset.replyLead);if(!lead)return;
 if(!lead.email){msg("#leadNotice","Zákazník nemá e-mailovou adresu.",true);return}
 $("#replyLeadId").value=lead.id;$("#replyRecipient").textContent=(lead.name||"Zákazník")+" · "+lead.email;
 $("#replyHistory").innerHTML=(Array.isArray(lead.communication)?lead.communication:[]).map(x=>'<div class="reply-item"><small>'+esc(when(x.created_at||x.sent_at))+' · '+esc(x.type==="outgoing"||x.direction==="out"?"Odesláno":"Zpráva")+'</small><p>'+esc(x.body||x.message||"")+'</p></div>').join("")||"<p>Zatím bez uložených zpráv.</p>";
 $("#replyMessage").value="";$("#replyNotice").textContent="";$("#replyModal").hidden=false;replyRequestId=null;
});
